begin;
-- Owner review records legal basis/evidence, not an automated legal opinion or
-- ETA acceptance. No legacy invoice, catalogue price, payment or tax is altered.
create table private.owner_tax_proposals(
 proposal_id uuid primary key,branch_id uuid not null references public.business_branches(branch_id),item_id uuid not null references public.business_catalog_items(item_id),
 base_version integer not null check(base_version>=0),spec jsonb not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp());
create table private.owner_tax_reviews(
 review_id uuid primary key,proposal_id uuid not null unique references private.owner_tax_proposals(proposal_id),decision text not null check(decision in('approve','reject')),
 reason text not null,acknowledgement jsonb,actor_id uuid not null references auth.users(id),session_id uuid not null,created_at timestamptz not null default clock_timestamp());
create table private.owner_tax_active(
 branch_id uuid not null references public.business_branches(branch_id),item_id uuid not null references public.business_catalog_items(item_id),
 version integer not null check(version>0),proposal_id uuid references private.owner_tax_proposals(proposal_id),actor_id uuid not null references auth.users(id),updated_at timestamptz not null default clock_timestamp(),primary key(branch_id,item_id));
create table private.owner_tax_commands(request_id uuid primary key,actor_id uuid not null,payload jsonb not null,result jsonb not null,created_at timestamptz not null default clock_timestamp());
create table private.owner_tax_defaults(branch_id uuid primary key references public.business_branches(branch_id),version integer not null check(version>0),display_mode text not null check(display_mode in('inclusive','exclusive')),default_rate numeric,actor_id uuid not null references auth.users(id),updated_at timestamptz not null default clock_timestamp());
create index owner_tax_proposal_item on private.owner_tax_proposals(branch_id,item_id,created_at desc,proposal_id);
create function private.owner_tax_immutable()returns trigger language plpgsql set search_path=pg_catalog as $$begin raise exception 'Tax review history is immutable'using errcode='55000';end$$;
do $$declare t text;begin foreach t in array array['owner_tax_proposals','owner_tax_reviews','owner_tax_active','owner_tax_commands','owner_tax_defaults']loop
 execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated,service_role',t);end loop;
 foreach t in array array['owner_tax_proposals','owner_tax_reviews','owner_tax_commands']loop execute format('create trigger immutable_tax_history before update or delete on private.%I for each row execute function private.owner_tax_immutable()',t);end loop;end$$;
create function private.require_owner_tax_branch(p_branch uuid)returns uuid language plpgsql volatile security definer set search_path=pg_catalog as $$begin
 if not coalesce(private.has_live_invoice_session(),false)or private.active_staff_role()is distinct from'owner'then raise exception 'Current confirmed owner session required'using errcode='42501';end if;
 if not exists(select 1 from public.business_branches where branch_id=p_branch and is_active)then raise exception 'Actual active branch required'using errcode='22023';end if;return auth.uid();end$$;
create function private.owner_tax_review_notice(p_language text)returns text language sql immutable set search_path=pg_catalog as $$select case p_language when'ar'then'أقر أنني راجعت التصنيف والنسبة وأساسهما القانوني مع المسؤول المختص، وأن الأدلة المشار إليها تخص هذا البند. هذا الإقرار ليس موافقة من مصلحة الضرائب.'when'en'then'I confirm the tax classification, rate and legal basis were reviewed with the responsible specialist and the referenced evidence applies to this item. This is not ETA approval.'end$$;
create function private.owner_tax_replay(p_request uuid,p_actor uuid,p_payload jsonb)returns jsonb language plpgsql volatile security definer set search_path=pg_catalog as $$declare c private.owner_tax_commands;begin
 if p_request is null then raise exception 'Exact request required'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-tax-command:'||p_request,0));select *into c from private.owner_tax_commands where request_id=p_request;
 if not found then return null;end if;if c.actor_id<>p_actor then raise exception 'Request unavailable'using errcode='42501';end if;if c.payload<>p_payload then raise exception 'Immutable tax command'using errcode='22023';end if;return c.result;end$$;
create function private.propose_owner_tax_classification(p_request uuid,p_branch uuid,p_item uuid,p_expected_version integer,p_spec jsonb)returns jsonb language plpgsql volatile security definer set search_path=pg_catalog as $$
declare actor uuid;payload jsonb;prior jsonb;spec jsonb;mode text;subtype text;rate numeric;current_version integer;pid uuid:=gen_random_uuid();result jsonb;begin
 actor:=private.require_owner_tax_branch(p_branch);
 if p_item is null or p_expected_version is null or p_expected_version<0 or not exists(select 1 from public.business_catalog_items where item_id=p_item and branch_id=p_branch)or jsonb_typeof(p_spec)is distinct from'object'or(select count(*)from jsonb_object_keys(p_spec))<>5 or not(p_spec?&array['tax_mode','rate_percent','eta_subtype','legal_basis','evidence_reference'])or jsonb_typeof(p_spec->'rate_percent')is distinct from'number'then raise exception 'Exact item, version and classification evidence required'using errcode='22023';end if;
 mode:=p_spec->>'tax_mode';rate:=(p_spec->>'rate_percent')::numeric;subtype:=upper(p_spec->>'eta_subtype');
 if mode is null or mode not in('inclusive','exclusive','exempt','non_taxable')or rate not between 0 and 999 or round(rate,2)<>rate or jsonb_typeof(p_spec->'legal_basis')is distinct from'string'or length(trim(p_spec->>'legal_basis'))not between 5 and 1000 or jsonb_typeof(p_spec->'evidence_reference')is distinct from'string'or length(trim(p_spec->>'evidence_reference'))not between 5 and 500 or subtype is null
 or(mode in('inclusive','exclusive')and(rate<=0 or subtype not in('V009','V010')))or(mode='exempt'and(rate<>0 or subtype not in('V003','V005','V006','V007','V008')))or(mode='non_taxable'and(rate<>0 or subtype<>'V004'))then raise exception 'Classification, rate, legal basis and evidence must match; no arbitrary tax waiver'using errcode='22023';end if;
 payload:=jsonb_build_object('kind','propose','branch',p_branch,'item',p_item,'version',p_expected_version,'spec',p_spec);prior:=private.owner_tax_replay(p_request,actor,payload);if prior is not null then return prior;end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-tax-item:'||p_branch||':'||p_item,0));select version into current_version from private.owner_tax_active where branch_id=p_branch and item_id=p_item for update;
 if coalesce(current_version,0)<>p_expected_version then raise exception 'Classification version conflict'using errcode='40001';end if;
 spec:=jsonb_build_object('tax_mode',mode,'rate_percent',rate,'tax_type','T1','eta_subtype',subtype,'legal_basis',trim(p_spec->>'legal_basis'),'evidence_reference',trim(p_spec->>'evidence_reference'));
 insert into private.owner_tax_proposals(proposal_id,branch_id,item_id,base_version,spec,actor_id)values(pid,p_branch,p_item,p_expected_version,spec,actor);
 result:=jsonb_build_object('proposal_id',pid,'state','pending_review','base_version',p_expected_version,'spec',spec,'active',false,'eta_accepted',false);
 insert into private.owner_tax_commands(request_id,actor_id,payload,result)values(p_request,actor,payload,result);
 insert into public.business_audit_log(actor,actor_id,action,entity,entity_id,branch_id,after_data)values(actor::text,actor,'owner_tax_classification_proposed','tax_classification',pid::text,p_branch,result);return result;end$$;
create function private.review_owner_tax_classification(p_request uuid,p_branch uuid,p_proposal uuid,p_expected_version integer,p_decision text,p_reason text,p_ack jsonb)returns jsonb language plpgsql volatile security definer set search_path=pg_catalog as $$
declare actor uuid;proposal private.owner_tax_proposals;current_row private.owner_tax_active;payload jsonb;prior jsonb;result jsonb;rid uuid:=gen_random_uuid();begin
 actor:=private.require_owner_tax_branch(p_branch);
 if p_proposal is null or p_expected_version is null or p_expected_version<0 or p_decision is null or p_decision not in('approve','reject')or length(trim(coalesce(p_reason,'')))not between 5 and 500 then raise exception 'Exact decision and reason required'using errcode='22023';end if;
 if p_decision='approve'and(jsonb_typeof(p_ack)is distinct from'object'or(select count(*)from jsonb_object_keys(p_ack))<>4 or p_ack->>'version'is distinct from'tax-review-v1'or p_ack->'reviewed'is distinct from'true'::jsonb or p_ack->>'language'is null or p_ack->>'language'not in('ar','en')or p_ack->>'text'is distinct from private.owner_tax_review_notice(p_ack->>'language'))then raise exception 'Explicit documented owner review required'using errcode='22023';end if;
 payload:=jsonb_build_object('kind','review','branch',p_branch,'proposal',p_proposal,'version',p_expected_version,'decision',p_decision,'reason',trim(p_reason),'ack',p_ack);prior:=private.owner_tax_replay(p_request,actor,payload);if prior is not null then return prior;end if;
 select *into proposal from private.owner_tax_proposals where proposal_id=p_proposal and branch_id=p_branch;
 if not found or not exists(select 1 from public.business_catalog_items where item_id=proposal.item_id and branch_id=p_branch)then raise exception 'Proposal unavailable'using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-tax-item:'||p_branch||':'||proposal.item_id,0));
 select *into current_row from private.owner_tax_active where branch_id=p_branch and item_id=proposal.item_id for update;
 if coalesce(current_row.version,0)<>p_expected_version or(p_decision='approve'and proposal.base_version<>p_expected_version)then raise exception 'Review version conflict'using errcode='40001';end if;
 if exists(select 1 from private.owner_tax_reviews where proposal_id=p_proposal)then raise exception 'Proposal already decided'using errcode='55000';end if;
 insert into private.owner_tax_reviews(review_id,proposal_id,decision,reason,acknowledgement,actor_id,session_id)values(rid,p_proposal,p_decision,trim(p_reason),case when p_decision='approve'then p_ack else null end,actor,(auth.jwt()->>'session_id')::uuid);
 if p_decision='approve'then insert into private.owner_tax_active values(p_branch,proposal.item_id,p_expected_version+1,p_proposal,actor,clock_timestamp())on conflict(branch_id,item_id)do update set version=excluded.version,proposal_id=excluded.proposal_id,actor_id=excluded.actor_id,updated_at=excluded.updated_at;end if;
 result:=jsonb_build_object('proposal_id',p_proposal,'review_id',rid,'state',case when p_decision='approve'then'owner_reviewed'else'rejected'end,'active_version',case when p_decision='approve'then p_expected_version+1 else p_expected_version end,'active',p_decision='approve','legally_verified_by_software',false,'eta_accepted',false);
 insert into private.owner_tax_commands(request_id,actor_id,payload,result)values(p_request,actor,payload,result);
 insert into public.business_audit_log(actor,actor_id,action,entity,entity_id,branch_id,reason,before_data,after_data)values(actor::text,actor,'owner_tax_classification_'||p_decision,'tax_classification',p_proposal::text,p_branch,trim(p_reason),to_jsonb(current_row),result);return result;end$$;
create function private.pause_owner_tax_classification(p_request uuid,p_branch uuid,p_item uuid,p_expected_version integer,p_reason text)returns jsonb language plpgsql volatile security definer set search_path=pg_catalog as $$declare actor uuid;oldrow private.owner_tax_active;payload jsonb;prior jsonb;result jsonb;begin
 actor:=private.require_owner_tax_branch(p_branch);
 if p_item is null or p_expected_version is null or p_expected_version<1 or length(trim(coalesce(p_reason,'')))not between 5 and 500 then raise exception 'Exact active classification and reason required'using errcode='22023';end if;
 payload:=jsonb_build_object('kind','pause','branch',p_branch,'item',p_item,'version',p_expected_version,'reason',trim(p_reason));prior:=private.owner_tax_replay(p_request,actor,payload);if prior is not null then return prior;end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-tax-item:'||p_branch||':'||p_item,0));select *into oldrow from private.owner_tax_active where branch_id=p_branch and item_id=p_item for update;
 if oldrow.version is distinct from p_expected_version then raise exception 'Classification version conflict'using errcode='40001';end if;
 if oldrow.proposal_id is null then raise exception 'Classification is already paused'using errcode='55000';end if;
 update private.owner_tax_active set proposal_id=null,version=version+1,actor_id=actor,updated_at=clock_timestamp()where branch_id=p_branch and item_id=p_item;
 result:=jsonb_build_object('state','paused','active_version',p_expected_version+1,'blocks_unreviewed_issuance',true,'zero_tax_fallback',false);
 insert into private.owner_tax_commands(request_id,actor_id,payload,result)values(p_request,actor,payload,result);
 insert into public.business_audit_log(actor,actor_id,action,entity,entity_id,branch_id,reason,before_data,after_data)values(actor::text,actor,'owner_tax_classification_paused','tax_classification',p_item::text,p_branch,trim(p_reason),to_jsonb(oldrow),result);return result;end$$;
create function private.resolve_owner_reviewed_tax(p_branch uuid,p_item uuid)returns jsonb language sql stable security invoker set search_path=pg_catalog as $$
 select p.spec||jsonb_build_object('classification_id',p.proposal_id,'review_id',r.review_id,'classification_version',a.version,'review_state','owner_reviewed','legally_verified_by_software',false,'eta_accepted',false)
 from private.owner_tax_active a join private.owner_tax_proposals p on p.proposal_id=a.proposal_id and p.branch_id=a.branch_id and p.item_id=a.item_id join private.owner_tax_reviews r on r.proposal_id=p.proposal_id and r.decision='approve'
 where a.branch_id=p_branch and a.item_id=p_item;
$$;
create function private.save_owner_tax_invoice_defaults(p_request uuid,p_branch uuid,p_expected_version integer,p_display_mode text,p_default_rate numeric,p_reason text)returns jsonb language plpgsql volatile security definer set search_path=pg_catalog as $$declare actor uuid;oldrow private.owner_tax_defaults;payload jsonb;prior jsonb;result jsonb;begin
 actor:=private.require_owner_tax_branch(p_branch);
 if p_expected_version is null or p_expected_version<0 or p_display_mode is null or p_display_mode not in('inclusive','exclusive')or(p_default_rate is not null and(p_default_rate::text in('NaN','Infinity','-Infinity')or p_default_rate<=0 or p_default_rate>999 or round(p_default_rate,2)<>p_default_rate))or length(trim(coalesce(p_reason,'')))not between 5 and 500 then raise exception 'Explicit display mode and optional positive default suggestion required'using errcode='22023';end if;
 payload:=jsonb_build_object('kind','defaults','branch',p_branch,'version',p_expected_version,'display_mode',p_display_mode,'default_rate',p_default_rate,'reason',trim(p_reason));prior:=private.owner_tax_replay(p_request,actor,payload);if prior is not null then return prior;end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-tax-defaults:'||p_branch,0));select *into oldrow from private.owner_tax_defaults where branch_id=p_branch for update;
 if coalesce(oldrow.version,0)<>p_expected_version then raise exception 'Defaults version conflict'using errcode='40001';end if;
 insert into private.owner_tax_defaults values(p_branch,p_expected_version+1,p_display_mode,p_default_rate,actor,clock_timestamp())on conflict(branch_id)do update set version=excluded.version,display_mode=excluded.display_mode,default_rate=excluded.default_rate,actor_id=excluded.actor_id,updated_at=excluded.updated_at;
 result:=jsonb_build_object('version',p_expected_version+1,'display_mode',p_display_mode,'default_rate',p_default_rate,'requires_item_review',true,'changes_existing_invoices',false);
 insert into private.owner_tax_commands(request_id,actor_id,payload,result)values(p_request,actor,payload,result);
 insert into public.business_audit_log(actor,actor_id,action,entity,entity_id,branch_id,reason,before_data,after_data)values(actor::text,actor,'owner_tax_defaults_saved','tax_defaults',p_branch::text,p_branch,trim(p_reason),to_jsonb(oldrow),result);return result;end$$;
create function private.get_owner_tax_invoice_settings(p_branch uuid,p_search text,p_after uuid)returns jsonb language plpgsql volatile security definer set search_path=pg_catalog as $$declare items jsonb;defaults jsonb;begin
 perform private.require_owner_tax_branch(p_branch);
 if p_search is null or length(p_search)>120 then raise exception 'Valid search required'using errcode='22023';end if;
 select to_jsonb(d)-'actor_id'into defaults from private.owner_tax_defaults d where branch_id=p_branch;
 select coalesce(jsonb_agg(to_jsonb(x)order by item_id),'[]')into items from(select c.item_id,c.name,c.name_en,c.price,c.item_type,coalesce(a.version,0)active_version,private.resolve_owner_reviewed_tax(p_branch,c.item_id)active_classification,
 (select coalesce(jsonb_agg(jsonb_build_object('proposal_id',z.proposal_id,'base_version',z.base_version,'spec',z.spec,'created_at',z.created_at)order by z.created_at desc,z.proposal_id),'[]')from(select p.*from private.owner_tax_proposals p where p.branch_id=p_branch and p.item_id=c.item_id and not exists(select 1 from private.owner_tax_reviews r where r.proposal_id=p.proposal_id)order by p.created_at desc,p.proposal_id limit 10)z)pending_proposals
 from public.business_catalog_items c left join private.owner_tax_active a on a.branch_id=c.branch_id and a.item_id=c.item_id where c.branch_id=p_branch and c.is_active and(p_after is null or c.item_id>p_after)and(c.name ilike'%'||p_search||'%'or c.name_en ilike'%'||p_search||'%')order by c.item_id limit 101)x;
 return jsonb_build_object('items',case when jsonb_array_length(items)>100 then items-100 else items end,'has_more',jsonb_array_length(items)>100,'defaults',defaults,'default_rate_assumed',false,'notice_version','tax-review-v1','notice_ar',private.owner_tax_review_notice('ar'),'notice_en',private.owner_tax_review_notice('en'),'owner_only',true,'eta_submission_enabled',false,'invoice_issuance_integrated',false);
end$$;
create function public.propose_owner_tax_classification(p_request uuid,p_branch uuid,p_item uuid,p_expected_version integer,p_spec jsonb)returns jsonb language sql security invoker set search_path=pg_catalog as $$select private.propose_owner_tax_classification(p_request,p_branch,p_item,p_expected_version,p_spec)$$;
create function public.review_owner_tax_classification(p_request uuid,p_branch uuid,p_proposal uuid,p_expected_version integer,p_decision text,p_reason text,p_ack jsonb)returns jsonb language sql security invoker set search_path=pg_catalog as $$select private.review_owner_tax_classification(p_request,p_branch,p_proposal,p_expected_version,p_decision,p_reason,p_ack)$$;
create function public.pause_owner_tax_classification(p_request uuid,p_branch uuid,p_item uuid,p_expected_version integer,p_reason text)returns jsonb language sql security invoker set search_path=pg_catalog as $$select private.pause_owner_tax_classification(p_request,p_branch,p_item,p_expected_version,p_reason)$$;
create function public.save_owner_tax_invoice_defaults(p_request uuid,p_branch uuid,p_expected_version integer,p_display_mode text,p_default_rate numeric,p_reason text)returns jsonb language sql security invoker set search_path=pg_catalog as $$select private.save_owner_tax_invoice_defaults(p_request,p_branch,p_expected_version,p_display_mode,p_default_rate,p_reason)$$;
create function public.get_owner_tax_invoice_settings(p_branch uuid,p_search text default '',p_after uuid default null)returns jsonb language sql security invoker set search_path=pg_catalog as $$select private.get_owner_tax_invoice_settings(p_branch,p_search,p_after)$$;
revoke all on function private.owner_tax_immutable(),private.require_owner_tax_branch(uuid),private.owner_tax_review_notice(text),private.owner_tax_replay(uuid,uuid,jsonb),private.resolve_owner_reviewed_tax(uuid,uuid),private.propose_owner_tax_classification(uuid,uuid,uuid,integer,jsonb),private.review_owner_tax_classification(uuid,uuid,uuid,integer,text,text,jsonb),private.pause_owner_tax_classification(uuid,uuid,uuid,integer,text),private.save_owner_tax_invoice_defaults(uuid,uuid,integer,text,numeric,text),private.get_owner_tax_invoice_settings(uuid,text,uuid),public.propose_owner_tax_classification(uuid,uuid,uuid,integer,jsonb),public.review_owner_tax_classification(uuid,uuid,uuid,integer,text,text,jsonb),public.pause_owner_tax_classification(uuid,uuid,uuid,integer,text),public.save_owner_tax_invoice_defaults(uuid,uuid,integer,text,numeric,text),public.get_owner_tax_invoice_settings(uuid,text,uuid)from public,anon,authenticated,service_role;
grant execute on function private.propose_owner_tax_classification(uuid,uuid,uuid,integer,jsonb),private.review_owner_tax_classification(uuid,uuid,uuid,integer,text,text,jsonb),private.pause_owner_tax_classification(uuid,uuid,uuid,integer,text),private.save_owner_tax_invoice_defaults(uuid,uuid,integer,text,numeric,text),private.get_owner_tax_invoice_settings(uuid,text,uuid),public.propose_owner_tax_classification(uuid,uuid,uuid,integer,jsonb),public.review_owner_tax_classification(uuid,uuid,uuid,integer,text,text,jsonb),public.pause_owner_tax_classification(uuid,uuid,uuid,integer,text),public.save_owner_tax_invoice_defaults(uuid,uuid,integer,text,numeric,text),public.get_owner_tax_invoice_settings(uuid,text,uuid)to authenticated;
notify pgrst,'reload schema';
commit;
